# Better design

for i in range(3):
    print("meow")

# Abstraction with parameterization

def main():
    meow(3)

# Meow some number of times
def meow(n):
    for i in range(n):
        print("meow")

main()

pizzas = {"cheese": 9, "pepperoni": 10}
for pie, price in pizzas.items():
    print(pie, price)

